#include <cstdio>
#include <string>
#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::string s, t;
    std::getline(std::cin, s);
    std::getline(std::cin, t);
    int n = (int)s.size(), m = (int)t.size();

    std::vector<int> prev(m + 1), cur(m + 1);
    for (int j = 0; j <= m; ++j) prev[j] = j;

    for (int i = 1; i <= n; ++i) {
        cur[0] = i;
        for (int j = 1; j <= m; ++j) {
            if (s[i - 1] == t[j - 1]) cur[j] = prev[j - 1];
            else cur[j] = 1 + std::min(std::min(prev[j], cur[j - 1]), prev[j - 1]);
        }
        std::swap(prev, cur);
    }
    printf("%d\n", prev[m]);
    return 0;
}
